#include <stdio.h>

#define MAXN 200000

static long long bitA[MAXN + 2];
static long long bitB[MAXN + 2];
static int N;

static void bit_add(long long bit[], int index, long long value) {
    while (index <= N) {
        bit[index] += value;
        index += index & -index;
    }
}

static long long bit_sum(const long long bit[], int index) {
    long long sum = 0;
    while (index > 0) {
        sum += bit[index];
        index -= index & -index;
    }
    return sum;
}

static void range_add(int left, int right, long long a, long long b) {
    bit_add(bitA, left, a);
    bit_add(bitB, left, b);

    if (right < N) {
        bit_add(bitA, right + 1, -a);
        bit_add(bitB, right + 1, -b);
    }
}

int main(void) {
    int M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    for (int k = 0; k < M; ++k) {
        int type, i;
        scanf("%d %d", &type, &i);

        if (type == 1 || type == 2) {
            int V;
            scanf("%d", &V);

            if (type == 1) {
                int right = i + V - 1;
                if (right > N) right = N;
                range_add(i, right, (long long)V + i, -1);
            } else {
                int left = i - V + 1;
                if (left < 1) left = 1;
                range_add(left, i, (long long)V - i, 1);
            }
        } else {
            long long a = bit_sum(bitA, i);
            long long b = bit_sum(bitB, i);
            printf("%lld\n", a + b * i);
        }
    }

    return 0;
}
